description:
Implement the Verilog module based on the following description.
Module E implements the boolean function z = a ^ b.

// Module F can be described by the following simulation waveform: 

If a = 1, b = 1, then z = 0.
If a = 0, b = 1, then z = 1.
If a = 0, b = 0, then z = 0.
If a = 1, b = 0, then z = 1.

// Now consider a top-level that uses two E submodules and two F submodules. The first input of all four submodules is connected to input 'a', and the second input of all four submodules is connected to 'b'. The output of the first E submodule is connected to a two-input OR gate, along with the output of the first F submodule. The second pair of E and F submodules is similarly connected to a NOR gate. The output of the OR and the NOR is connected to an AND, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input a,
    input b,
    output z);

code:
module E(
    input a,
    input b,
    output z
);
    assign z = a ^ b;
endmodule

module F(
    input a,
    input b,
    output z
);
    assign z = a ^ b;
endmodule

module top_module(
    input a,
    input b,
    output z
);
    wire e1_out, e2_out, f1_out, f2_out;
    wire or_out, nor_out;

    E e1(.a(a), .b(b), .z(e1_out));
    E e2(.a(a), .b(b), .z(e2_out));
    F f1(.a(a), .b(b), .z(f1_out));
    F f2(.a(a), .b(b), .z(f2_out));

    assign or_out = e1_out | f1_out;
    assign nor_out = ~(e2_out | f2_out);

    assign z = or_out & nor_out;
endmodule

