  1: Segments <= 8'B11111001; 
  2: Segments <= 8'B10100100; 
  3: Segments <= 8'B10110000; 
  4: Segments <= 8'B10011001; 
  5: Segments <= 8'B10010010; 
  6: Segments <= 8'B10000010; 
