  9: Segments <= 8'B10010000; 
  10: Segments <= 8'B10001000; 
  11: Segments <= 8'B10000011; 
  12: Segments <= 8'B11000110; 
  13: Segments <= 8'B10100001; 
  14: Segments <= 8'B10000110; 
  15: Segments <= 8'B10001110; 
  default: Segments <= 8'B00000000; 
  endcase 
