description:
Design a square wave generator that outputs a HIGH signal for three clock cycles and a LOW signal for one clock cycle, creating a repeating wave pattern. The output can be reset to LOW whenever the reset input is activated. The generator transitions between four distinct states, controlling the output accordingly based on the current state each time there is a rising edge of the clock.
module top_module(
    input clk,
    input reset,
    output reg out
);

code:
module top_module(
    input clk,
    input reset,
    output reg out
);reg [1:0] state;
always @ (posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        out <= 0;
    end else begin
        case (state)
            2'b00: begin
                out <= 0;
                state <= 2'b01;
            end
            2'b01: begin
                out <= 1;
                state <= 2'b10;
            end
            2'b10: begin
                out <= 1;
                state <= 2'b11;
            end
            2'b11: begin
                out <= 0;
                state <= 2'b00;
            end
        endcase
    end
end

endmodule

